import pymupdf, glob, os, re

# For each sheet, let's map text and drawing blocks and see which view contains each callout
def map_views_and_callouts(folder):
    sheet_data = {}
    for f in sorted(glob.glob(os.path.join(folder, '*.pdf'))):
        sname = os.path.basename(f).replace('.pdf', '')
        sheet_id = sname.split('_')[-1]
        doc = pymupdf.open(f)
        page = doc[0]
        blocks = page.get_text('blocks')
        # get all view titles
        # find callout bubbles (l1, l2) and their bboxes
        sheet_data[sheet_id] = {'views': [], 'callouts': []}

        # let's look at lines and their bboxes
        lines_with_pos = []
        for b in blocks:
            text = b[4]
            lines = text.split('\n')
            for l in lines:
                l_str = l.strip()
                if l_str:
                    lines_with_pos.append((l_str, b[:4]))

        # find view titles
        for l_str, bbox in lines_with_pos:
            if any(k in l_str.upper() for k in ['PLAN', 'SECTION', 'DETAIL', 'ELEVATION', 'SCHEDULE']) and 'SHEET TITLE' not in l_str.upper():
                sheet_data[sheet_id]['views'].append((l_str, bbox))

        # find callouts
        for i in range(len(lines_with_pos)-1):
            l1, b1 = lines_with_pos[i]
            l2, b2 = lines_with_pos[i+1]
            if re.match(r'^[A-Z0-9]{1,2}$', l1) and re.match(r'^[ACDEGIMS-]{1,2}-[0-9]{3}$', l2):
                sheet_data[sheet_id]['callouts'].append({'callout': (l1, l2), 'pos': b1})

    return sheet_data

